// AUTO SELECT SERVICE + SCROLL
document.querySelectorAll(".book-btn").forEach(btn => {
  btn.addEventListener("click", () => {
    const selectedService = btn.getAttribute("data-service");

    document.getElementById("service").value = selectedService;

    document.getElementById("bookingForm")
      .scrollIntoView({ behavior: "smooth" });
  });
});

// FORM SUBMIT
document.getElementById("bookingForm").addEventListener("submit", async (e) => {
  e.preventDefault();

  const data = {
    service: document.getElementById("service").value,
    name: document.getElementById("name").value,
    email: document.getElementById("email").value,
    phone: document.getElementById("phone").value,
    message: document.getElementById("message").value
  };

  const msg = document.getElementById("msg");
  msg.innerText = "Booking in progress...";

  try {
    const res = await fetch("http://localhost:3000/booking", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data)
    });

    const result = await res.json();

    if (res.ok) {
      msg.style.color = "green";
      msg.innerText = "✅ Booking successful!";
      document.getElementById("bookingForm").reset();
    } else {
      msg.style.color = "red";
      msg.innerText = result.message || "❌ Booking failed";
    }
  } catch {
    msg.style.color = "red";
    msg.innerText = "❌ Server error";
  }
});
